  theme: ThemeLike,
  token: string,
  fallback: string,
  text: string,
): string {
  const trimmedToken = token.trim();
  if (TOKEN.test(trimmedToken)) {
    try {
      return theme.fg(trimmedToken, text);
    } catch {
