private centralInvalidationCheck(): void {
  if (this.redoStack.length === 0) return;
  if (this.currentTransition !== "none") return;
  this.clearRedoStack();
}

private getCountedCommandKeys(commandKey: string): string[] {
  return [...this.prefixCount, commandKey];
}

private beginRepeatableCommand(keys: string[]): void {
  if (this.replayingRepeat) return;
  this.repeatRecording = {
    keys: [...keys],
    startText: this.getText(),
    captureInsert: false,
  };
}

private beginRepeatableNormalCommand(commandKey: string): void {
  this.beginRepeatableCommand(this.getCountedCommandKeys(commandKey));
}

private appendRepeatableKey(key: string): void {
  if (this.replayingRepeat) return;
  this.repeatRecording?.keys.push(key);
}

private captureRepeatableInsertInput(): void {
  if (this.replayingRepeat || !this.repeatRecording) return;
  this.repeatRecording.captureInsert = true;
}

private cancelRepeatableCommand(): void {
  if (this.replayingRepeat) return;
  this.repeatRecording = null;
}

private commitRepeatableCommandIfChanged(): void {
  if (this.replayingRepeat) return;

  const recording = this.repeatRecording;
  this.repeatRecording = null;
  if (!recording || recording.keys.length === 0) return;

  if (this.getText() !== recording.startText) {
    this.lastRepeatableCommand = [...recording.keys];
  }
}

private repeatLastCommand(): void {
  const command = this.lastRepeatableCommand;
  const repeatCount = Math.max(1, Math.min(MAX_COUNT, this.takeTotalCount(1)));
  if (!command || command.length === 0) return;

  const previousRecording = this.repeatRecording;
  this.repeatRecording = null;
  this.replayingRepeat = true;
  try {
    for (let i = 0; i < repeatCount; i++) {
      for (const key of command) {
        this.handleInput(key);
      }
    }
  } finally {
    this.replayingRepeat = false;
    this.repeatRecording = previousRecording;
  }
}

